#!/bin/sh
# GENERATED by infra/hosts/backup/steps.ts (render): do not edit.
# The daily pair (Run 6.5, P-118 … P-120, D-51, D-52), run by mykey-backup.service:
# begin the capture (drain, freeze), take the three artifacts, record the
# candidate (writing reopens), then pack, upload, read back, check and sign.
# Exit 75: busy (the timer tries again). Every secret is a file; none is an
# argument or an environment value.
set -eu
umask 077

host_env=${MYKEY_HOST_ENV:-/etc/mykey/host.env}
setting() { sed -n "s/^$1=//p" "$host_env" | tail -n 1; }

# backup.sh recover (mykey-capture-recover at boot; mykey-backup's ExecStopPost):
# release a freeze a dead capture left, and remove every pair tmpfs left behind.
if [ "${1:-}" = recover ]; then
  /opt/mykey/hosts/ops-run.sh capture -- capture --step abort --owner backup --reason aborted
  for dir in /var/lib/mykey/pairs/*; do
    [ -d "$dir" ] || continue
    umount "$dir" 2>/dev/null || true
    rm -rf "$dir"
  done
  exit 0
fi
[ "$#" -eq 0 ] || { echo "usage: backup.sh [recover]" >&2; exit 64; }

begun=$(/opt/mykey/hosts/ops-run.sh capture -- capture --step begin --owner backup) || exit $?
pair=$(printf '%s' "$begun" | sed -n 's/.*"pairId":"\([0-9a-f-]*\)".*/\1/p')
case "$pair" in
  ????????-????-????-????-????????????) ;;
  *) echo "backup: no pair id from capture begin" >&2; exit 1 ;;
esac
root="/var/lib/mykey/pairs/$pair"
released=false
finish() {
  status=$?
  if [ "$released" = false ]; then
    /opt/mykey/hosts/ops-run.sh capture -- capture --step abort --owner backup --reason aborted >&2 || true
  fi
  umount "$root" 2>/dev/null || true
  rmdir "$root" 2>/dev/null || true
  exit "$status"
}
trap finish EXIT INT TERM

install -d -m 0711 /var/lib/mykey/pairs
mkdir -m 0700 "$root"
mount -t tmpfs -o size=1g,mode=0700,uid=1000,gid=1000,nosuid,nodev,noexec tmpfs "$root"
install -d -m 0700 -o 1000 -g 1000 "$root/in" "$root/artifacts"
printf '%s\n' "$begun" > "$root/begin.json"

# The frozen part: at most 120 s (FROZEN_DEADLINE_MS); then the
# watchdog's TERM runs the trap, which aborts the capture.
( sleep 120; kill -TERM $$ ) &
watchdog=$!
pw=$(sed 's/[\\:]/\\&/g' /etc/mykey/secrets/ops/backup_reader)
printf 'postgres:5432:*:backup_reader:%s\n' "$pw" > "$root/in/pgpass"
pw=
chown 1000:1000 "$root/in/pgpass"
: > "$root/artifacts/postgres.dump" && docker run --rm --network mykey_db --read-only --cap-drop ALL --security-opt no-new-privileges --tmpfs /tmp --user 1000:1000 -v "$root/in/pgpass:/run/mykey/pgpass:ro" -e PGPASSFILE=/run/mykey/pgpass -v /etc/mykey/pki/ca.crt:/run/mykey/ca.crt:ro -v "$root/artifacts/postgres.dump:/run/mykey/postgres.dump" --entrypoint pg_dump postgres@sha256:e3d24f6906d0760bf4da0dae872415391ededefad23fd471c47dc53b0ddf3c42 --format=custom --file=/run/mykey/postgres.dump --dbname='host=postgres port=5432 dbname=postgres user=backup_reader sslmode=verify-full sslrootcert=/run/mykey/ca.crt'
rm -f "$root/in/pgpass"
PGPASSWORD=$(cat /etc/mykey/secrets/postgres/superuser-password)
export PGPASSWORD
docker exec -e PGPASSWORD -u postgres mykey-postgres-1 pg_dumpall --globals-only --no-role-passwords -U postgres > "$root/artifacts/globals.sql"
PGPASSWORD=
printf '{"role_id":"%s","secret_id":"%s"}' "$(cat /etc/mykey/secrets/backup-approle/role-id)" "$(cat /etc/mykey/secrets/backup-approle/secret-id)" > "$root/in/login.json"
curl --fail --silent --show-error --max-time 60 --cacert /etc/mykey/pki/ca.crt --resolve openbao:8200:10.78.3.2 --data @"$root/in/login.json" https://openbao:8200/v1/auth/approle/login | sed -n 's/.*"client_token":"\([^"]*\)".*/X-Vault-Token: \1/p' > "$root/in/bao-header"
rm -f "$root/in/login.json"
curl --fail --silent --show-error --max-time 300 --cacert /etc/mykey/pki/ca.crt --resolve openbao:8200:10.78.3.2 -H @"$root/in/bao-header" -o "$root/artifacts/openbao.snap" https://openbao:8200/v1/sys/storage/raft/snapshot
rm -f "$root/in/bao-header"

health=$(curl --fail --silent --max-time 30 --cacert /etc/mykey/pki/ca.crt --resolve openbao:8200:10.78.3.2 https://openbao:8200/v1/sys/health)
seal=$(curl --fail --silent --max-time 30 --cacert /etc/mykey/pki/ca.crt --resolve openbao:8200:10.78.3.2 https://openbao:8200/v1/sys/seal-status)
api_image=$(setting API_IMAGE)
{
  printf 'host_instance_id=%s\n' "$(cat /etc/machine-id)"
  printf 'backend_incarnation=%s\n' "$(printf '%s' "$health" | sed -n 's/.*"cluster_id":"\([^"]*\)".*/\1/p')"
  printf 'release_build=%s\n' "${api_image##*:}"
  printf 'kms_key_id=%s\n' "$(setting MYKEY_KMS_SEAL_KEY_ID)"
  printf 'seal_name=%s\n' "$(printf '%s' "$seal" | sed -n 's/.*"type":"\([^"]*\)".*/\1/p')"
  printf 'tool_openbao=%s\n' "$(printf '%s' "$health" | sed -n 's/.*"version":"\([^"]*\)".*/\1/p')"
  printf 'tool_postgres=%s\n' "18.6"
  printf 'tool_restic=%s\n' "0.19.1"
} > "$root/facts"
chown -R 1000:1000 "$root"

/opt/mykey/hosts/ops-run.sh pair -- pair --step manifest --pair "$pair"
/opt/mykey/hosts/ops-run.sh capture -- capture --step record --owner backup --pair "$pair" --manifest "$root/manifest.json"
released=true
kill "$watchdog" 2>/dev/null || true

# Writing is open again. The pair is a candidate until it is verified.
install -d -m 0700 -o 1000 -g 1000 "$root/repo"
docker run --rm --network none --read-only --cap-drop ALL --security-opt no-new-privileges --tmpfs /tmp --user 1000:1000 -e RESTIC_PASSWORD_FILE=/run/mykey/restic-password -v /etc/mykey/secrets/backup/password:/run/mykey/restic-password:ro -v "$root/repo:/repo" restic/restic@sha256:136600b6ff6843d61d355f7f71f460a166429f35de6fd11b568fece3c9a4d510 --repo /repo --no-cache init
docker run --rm --network none --read-only --cap-drop ALL --security-opt no-new-privileges --tmpfs /tmp --user 1000:1000 -e RESTIC_PASSWORD_FILE=/run/mykey/restic-password -v /etc/mykey/secrets/backup/password:/run/mykey/restic-password:ro -v "$root/repo:/repo" -v "$root/artifacts:/artifacts:ro" restic/restic@sha256:136600b6ff6843d61d355f7f71f460a166429f35de6fd11b568fece3c9a4d510 --repo /repo --no-cache backup --host mykey /artifacts
tar -C "$root" -cf "$root/bundle.tar" repo
rm -rf "$root/repo"
chown 1000:1000 "$root/bundle.tar"
/opt/mykey/hosts/ops-run.sh pair -- pair --step upload --pair "$pair"
mkdir -p "$root/restore/out" && tar -C "$root/restore" -xf "$root/downloaded.tar"
chown -R 1000:1000 "$root/restore"
set +e
docker run --rm --network none --read-only --cap-drop ALL --security-opt no-new-privileges --tmpfs /tmp --user 1000:1000 -e RESTIC_PASSWORD_FILE=/run/mykey/restic-password -v /etc/mykey/secrets/backup/password:/run/mykey/restic-password:ro -v "$root/restore/repo:/repo" restic/restic@sha256:136600b6ff6843d61d355f7f71f460a166429f35de6fd11b568fece3c9a4d510 --repo /repo --no-cache check --read-data > "$root/check.log" 2>&1
printf '%s\n' "$?" > "$root/check.status"
set -e
docker run --rm --network none --read-only --cap-drop ALL --security-opt no-new-privileges --tmpfs /tmp --user 1000:1000 -e RESTIC_PASSWORD_FILE=/run/mykey/restic-password -v /etc/mykey/secrets/backup/password:/run/mykey/restic-password:ro -v "$root/restore/repo:/repo" -v "$root/restore/out:/out" restic/restic@sha256:136600b6ff6843d61d355f7f71f460a166429f35de6fd11b568fece3c9a4d510 --repo /repo --no-cache restore latest --target /out >/dev/null
chown 1000:1000 "$root/check.log" "$root/check.status"
/opt/mykey/hosts/ops-run.sh pair -- pair --step verify --pair "$pair"
